using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A binary search tree in each language whose insert calls itself on node.left and node.right as statements of their own,
/// throwing away the new node it gives back, with the change that keeps it - node.left = insert(node.left, value) - for both;
/// and the same trees keeping it, which are left alone. Each row is what the check gave for the program when these were written.
/// </summary>
public class NewNodeLostTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes.</summary>
