    public void AnInsertThatKeepsItIsLeftAlone(string fileName, string code)
    {
        Assert.DoesNotContain(LogicPatterns.Scan(Program(fileName, code)), finding => finding.PatternId.EndsWith("new-node-lost", StringComparison.Ordinal));
    }
}
